import json
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path


ROOT = Path(__file__).resolve().parent


class ExportCalendarTest(unittest.TestCase):
    def export(self, *args):
        return subprocess.check_output(
            [sys.executable, "export_calendar.py", *args], cwd=ROOT
        )

    def test_default_batch(self):
        self.assertEqual(
            self.export(),
            b"east\tSafety walk\tOak\nwest\tDesk  check\tElm\n",
        )

    def test_selected_batch(self):
        slots = [
            {"id": "south", "title": "First\n\nSecond  shift", "room": "Ash"},
            {"id": "north", "title": "\r\nThird\u2028", "room": "Birch"},
        ]
        with tempfile.TemporaryDirectory() as directory:
            batch_path = Path(directory) / "batch.json"
            batch_path.write_text(json.dumps(slots), encoding="utf-8")
            output = self.export(str(batch_path))
        self.assertEqual(
            output,
            b"south\tFirst  Second  shift\tAsh\nnorth\t Third \tBirch\n",
        )

